// Weekly difficulty: the UTC weekday picks a tier (its monsters and rules) and
// a target for the capped human gap (cappedGap: how much harder a day is for
// the human-like bot than for the certifying search), rising every day from
// Monday to Saturday. Generation assembles each day from the floors of several
// candidate layouts so that their gaps add up to the target
// (src/generation.js). src/calibration.js (generated by
// scripts/calibrate-difficulty.mjs) maps each (tier, piece) to the knobs whose
// layouts land near the tier's targets. See docs/generation.md.
//
// Route measurements are evidence of tactical pressure, not shortest-path
// bounds or a claim that every winning strategy encounters these decisions.
import { CALIBRATION } from './calibration.js';
import { PIECE_COUNTS } from './pieces.js';

// This module imports no game module: src/monster-ai.js reads the tiers while
// it loads, and the rules import the monsters, so a cycle back here (once
// through the human-like bot) left DIFFICULTY_TIERS unset for any page or
// test that imported this module first.
/** The human-like bot (src/human-bot.js) gives up a floor after this many moves. */
export const HUMAN_MOVE_CAP = 40;

/** UTC weekday (0 = Sunday) → tier. Monday is easiest; the weekend is hardest. */
export const WEEKDAY_TIERS = Object.freeze(['fiendish', 'gentle', 'fair', 'tricky', 'tough', 'tough', 'fiendish']);

/** How much harder each day from Monday to Saturday is than the day before, in capped human gap. */
export const TARGET_STEP = 1.5;
/**
 * UTC weekday (0 = Sunday) → the capped human gap the public edition aims at:
 * Monday 2.5, then TARGET_STEP harder every day to Saturday's 10, the hardest;
 * Sunday matches Saturday. Like the New York Times crossword, the week climbs
 * from Monday to Saturday. Thursday and Friday share the Tough monsters and
 * may play alike. The range is what short floors reach (MAX_FLOOR_PAR): with
 * every floor's par at 10 or less, Tough days top out around 8 to 9 and
 * Fiendish ones around 10 (docs/generation.md, "Weekly difficulty").
 */
export const WEEKDAY_TARGETS = Object.freeze([10, 2.5, 4, 5.5, 7, 8.5, 10]);

/**
 * UTC weekday (0 = Sunday) → how many squares of the monster pawns'
 * promotion rank (the player's side) stay open on a floor where they live;
 * the rest are barricades (src/rules.js promotionBarricades). Two from Monday
 * to Thursday, so a pawn rarely crowns; every other square from Friday to
 * Sunday, so crowning stays a threat on the hardest days. In the bot's runs on
 * such floors a pawn crowned in 39% of runs with no barricades, 20% with every
 * other square walled and 10% with six of the eight (docs/generation.md).
 */
export const WEEKDAY_OPEN_PROMOTION_FILES = Object.freeze([4, 2, 2, 2, 2, 4, 4]);
/** The open promotion squares for a canonical YYYY-MM-DD date (two for anything else). */
export const openPromotionFiles = (date) => WEEKDAY_OPEN_PROMOTION_FILES[new Date(`${date}T12:00:00Z`).getUTCDay()] ?? 2;

const targetsOf = (id) => [...new Set(WEEKDAY_TARGETS.filter((_, day) => WEEKDAY_TIERS[day] === id))].sort((a, b) => a - b);
const defineTier = (rank, name, minFloorMoves, id) => {
  const targets = targetsOf(id);
  return Object.freeze({
    rank, name, minFloorMoves, targets: Object.freeze(targets),
    target: targets.reduce((sum, value) => sum + value, 0) / targets.length,
    band: Object.freeze([targets[0] - TARGET_STEP / 2, targets.at(-1) + TARGET_STEP / 2]),
  });
};
/**
 * Tiers from easiest to hardest. The weekday, not the gap, picks an edition's
 * tier, and the rank sets how smart the monsters are (src/monster-ai.js).
 * `targets` are the WEEKDAY_TARGETS of the tier's days (Tough has Thursday's
 * and Friday's), `target` their mean (for a tier played on another date, in
 * tooling) and `band` the range within half a step of them; neighbors share a
 * boundary. Calibration fits each (tier, piece) to its band.
 * `minFloorMoves`: a certified route must spend at least that many moves on
 * every floor; generation never takes a floor cleared faster. Every tier now
 * has none: the no-freebie rule (3 from Tricky on) went with short floors,
 * since a floor the route clears in two moves that a person needs several to
 * find is exactly the clever short floor the week climbs with (MAX_FLOOR_PAR).
 * A list of three numbers sets each floor's own minimum instead
 * (floorMinimums; tooling uses that to compare rules).
 */
export const DIFFICULTY_TIERS = Object.freeze({
  gentle: defineTier(1, 'Gentle', 0, 'gentle'),
  fair: defineTier(2, 'Fair', 0, 'fair'),
  tricky: defineTier(3, 'Tricky', 0, 'tricky'),
  tough: defineTier(4, 'Tough', 0, 'tough'),
  fiendish: defineTier(5, 'Fiendish', 0, 'fiendish'),
});
export const TIER_IDS = Object.freeze(Object.keys(DIFFICULTY_TIERS));

/** The tier of the public edition for a canonical YYYY-MM-DD date. */
export function tierForDate(date) {
  return WEEKDAY_TIERS[new Date(`${date}T12:00:00Z`).getUTCDay()];
}

/**
 * The capped human gap an edition of `tier` aims at on a canonical date: its
 * weekday's target when the tier is the date's own (the public edition), else
 * the tier's mean target.
 */
export function targetForDate(date, tierId = tierForDate(date)) {
  const weekday = new Date(`${date}T12:00:00Z`).getUTCDay();
  return WEEKDAY_TIERS[weekday] === tierId ? WEEKDAY_TARGETS[weekday] : DIFFICULTY_TIERS[tierId].target;
}

/** Newspaper label, e.g. "Difficulty: Tough". */
export function tierLabel(date, tier = tierForDate(date)) {
  return `Difficulty: ${DIFFICULTY_TIERS[tier].name}`;
}

/**
 * No floor's par (src/par.js, the human-like bot's usual moves there) should
 * pass this: floors stay a few moves long, and the week climbs by how much
 * cleverness those moves take, not by how many there are. Generation prefers
 * any assembly whose floors all keep to it over one that is closer to the
 * day's target (src/generation.js rankFloors); only a day none of whose
 * candidates can keep a floor to it takes the shortest it has.
 */
export const MAX_FLOOR_PAR = 10;
/**
 * The longest a floor may run when no candidate keeps it to MAX_FLOOR_PAR,
 * mostly a floor of eight pawn targets: past it, generation searches more
 * layouts (src/generation.js EXTRA_ATTEMPTS) until no floor is.
 */
export const LONG_FLOOR_PAR = 14;

/** Knobs used when a (tier, piece) pair has no calibrated row. */
export const DEFAULT_KNOBS = Object.freeze({ obstacleBase: 7, decoys: 2, scatter: 0, guards: 0, screens: 0, minThreatenedDecisions: 2 });

/**
 * Every floor keeps at least this many decoys beside its targets. A floor of
 * targets alone has no decoy to take for gold and, on the king floor, no royal
 * guard. The calibration grid never measures fewer
 * (scripts/calibrate-difficulty.mjs), and knobsFor raises an older table row
 * that has fewer.
 */
export const MIN_DECOYS = 1;

/**
 * Generation knobs for a tier and the day's piece:
 * - obstacleBase: walls on the first floor; each later floor adds one.
 * - decoys (MIN_DECOYS-4): residents beside each floor's targets (usually 2).
 * - minThreatenedDecisions: a certificate must make at least this many moves
 *   with a committed enemy attack lane on the board.
 * - scatter (0/1): non-pawn targets start in the back four rows, off every
 *   line the player's piece covers from its start square (src/rules.js).
 * - guards (0-2): decoys moved beside a target, where they strike a player who takes it.
 * - screens (0-3): walls placed first on the squares that cut the longest open
 *   lines into the targets, so long-range pieces must close in to capture.
 */
export function knobsFor(tier, piece) {
  if (!Object.hasOwn(DIFFICULTY_TIERS, tier)) throw new RangeError('Unknown difficulty tier.');
  const knobs = { ...DEFAULT_KNOBS, ...(CALIBRATION[tier]?.[piece] ?? {}) };
  return Object.freeze({ ...knobs, decoys: Math.max(MIN_DECOYS, knobs.decoys) });
}

/**
 * One number per certified edition, from its certificate's verifier metrics
 * (src/fairness.js verifyWinningRoute) and the day's piece. Higher is harder.
 * Kept for reference beside the tiers' measure (cappedGap): it says how
 * dangerous the certified route was, not how hard a route is to find.
 *
 *   pressure = threatenedDecisions + 2 × narrowEscapes + turns / 4 + 20 × unsafeShare
 *   score    = pressure / √(slack left at the end of the route)
 *
 * - threatenedDecisions: moves made with a committed attack lane on the board;
 * - narrowEscapes: moves where exactly one legal move was safe;
 * - turns / 4: route length, i.e. how much there is to plan;
 * - unsafeShare: unsafe alternatives / legal alternatives over the route, i.e.
 *   how likely a careless move is to be captured;
 * - slack left: the piece's army count (pawn 8, rook/knight/bishop 2, queen 1)
 *   minus the captures the route took (pawn days only), with diminishing
 *   returns, hence the square root. It once counted the lives a run started
 *   with; it stays so every certificate keeps its score.
 * It measures one witnessed route, not a shortest or forced one.
 */
export function difficultyScore(metrics, piece) {
  const share = metrics.legalAlternatives ? metrics.unsafeAlternatives / metrics.legalAlternatives : 0;
  const pressure = metrics.threatenedDecisions + 2 * metrics.narrowEscapes + metrics.turns / 4 + 20 * share;
  const slack = Math.max(1, PIECE_COUNTS[piece] - metrics.hits);
  return Math.round(pressure / Math.sqrt(slack) * 10) / 10;
}

/**
 * How much harder a day is for a person than for the search, beside
 * difficultyScore (which measures the certified route alone). Per floor: the
 * human-like bot's expected moves there (src/human-bot.js humanPar: the mean
 * of its runs from the floor's standard start, a failed run counting as the
 * whole move cap) minus the certified route's moves. Returns those per floor
 * (`floors`), the share of runs that failed per floor (`failed`) and their sum
 * (`total`), rounded to tenths. Higher is harder. The raw gap, for
 * measurement: one failed floor costs the cap minus the route (about 30), so
 * the bot's blind spots swamp it. The tiers use cappedGap.
 */
export function humanGap({ results, certified }, cap = HUMAN_MOVE_CAP) {
  const round = (value) => Math.round(value * 10) / 10;
  const floors = results.map((runs, floor) => runs.reduce((sum, run) => sum + (run.won ? run.moves : cap), 0) / runs.length - certified[floor]);
  return {
    floors: floors.map(round),
    failed: results.map((runs) => round(runs.filter((run) => !run.won).length / runs.length)),
    total: round(floors.reduce((sum, gap) => sum + gap, 0)),
  };
}

/** In the capped human gap, no run counts more than this many extra moves, and a failed run counts exactly this. */
export const GAP_RUN_CAP = 10;
/**
 * How much each floor counts in the capped human gap: all three the same.
 * The king floor counted half while par's bot left its recruit on Auto there
 * and failed 72% of a bishop's king-floor runs. With the steered recruit par
 * assumes and a king recruit on every king floor, the bot fails 0-18% of
 * king-floor runs, as on floors 1 and 2 (docs/generation.md, "Stage 2 bands").
 */
export const GAP_FLOOR_WEIGHTS = Object.freeze([1, 1, 1]);

/**
 * The capped human gap: what each day's target measures (WEEKDAY_TARGETS),
 * from the human-like bot's runs (src/human-bot.js humanPar: `results`, each
 * floor's runs from its standard start) and the certified route's moves per
 * floor (`certified`). Per run, its moves beyond the route's on that floor,
 * at least 0 (a run that beats the route is as easy as it gets) and at most
 * GAP_RUN_CAP, which is also what a failed run counts; per floor, the mean
 * of its runs; then the floors' sum, weighted by GAP_FLOOR_WEIGHTS and
 * rounded to tenths. 0 is a day the bot plays as well as the search; the
 * most is 30. Unlike humanGap, one hopeless floor (the bot's blind spots,
 * mostly king floors and pawn days) can't swamp the others: it costs at most
 * 10, a slow floor's worth.
 */
export function cappedGap(human) {
  const points = floorGapPoints(human);
  const floors = points.map((value, floor) => value / Math.max(1, human.results[floor].length));
  return Math.round(floors.reduce((sum, gap, floor) => sum + (GAP_FLOOR_WEIGHTS[floor] ?? 1) * gap, 0) * 10) / 10;
}

/**
 * The capped human gap floor by floor, before the means: each floor's run
 * values (0 to GAP_RUN_CAP each, see cappedGap) summed. Whole numbers, so
 * generation can add up floors taken from different candidates exactly
 * (src/generation.js rankFloors); a floor's gap is its points over its runs.
 */
export function floorGapPoints({ results, certified }) {
  return results.map((runs, floor) => runs.reduce((sum, run) => sum
    + (run.won ? Math.min(GAP_RUN_CAP, Math.max(0, run.moves - certified[floor])) : GAP_RUN_CAP), 0));
}

/**
 * Each floor's minimum moves under a freebie rule: a number applies to every
 * floor, a list gives floors 1 to 3 their own (0 or missing: no minimum).
 */
export function floorMinimums(rule) {
  return [0, 1, 2].map((floor) => (Array.isArray(rule) ? rule[floor] ?? 0 : rule ?? 0));
}

/**
 * True when a certified route clears some floor in fewer moves than the
 * tier's `minFloorMoves` (or `minimum`, any floorMinimums rule). `floorMoves`
 * (src/fairness.js) lists the moves each floor took until its challenge was
 * complete.
 */
export function freebieFloor(metrics, tier, minimum = DIFFICULTY_TIERS[tier]?.minFloorMoves ?? 0) {
  const minimums = floorMinimums(minimum);
  return (metrics?.floorMoves ?? []).some((moves, floor) => moves < (minimums[floor] ?? 0));
}

/** Distance from a capped human gap to a tier's band (half a step around its targets); 0 inside it. */
export function bandDistance(gap, tier) {
  const [low, high] = DIFFICULTY_TIERS[tier].band;
  return gap < low ? low - gap : gap > high ? gap - high : 0;
}
